#!/usr/bin/env python3
from ansible_builder.requirements import sanitize_requirements

requirements = {
    'test.collection': [
        'ansible',           # should be excluded
        'pytest',            # should be excluded  
        'yamllint>=1.26.0',  # should be preserved
        'ansible-lint>=5.0.0',  # should be preserved
        'requests>=2.25.0'   # should be preserved
    ]
}

result = sanitize_requirements(requirements)

print("Result:")
for req in result:
    print(f"  {req}")

# Check what's actually happening
print("\nChecking for ansible:")
for req in result:
    if 'ansible' in req.lower():
        print(f"  Found: {req}")

print("\nChecking for pytest:")  
for req in result:
    if 'pytest' in req.lower():
        print(f"  Found: {req}")
